    function createCreated(uint arg) public {
        innerContract = new CreatedWithEvent(arg);
    }

    function overrideCreated(address arg) public {
        innerContract = CreatedWithEvent(payable(arg));
    }

    function getInnerContractX() public view returns (uint) {
        return innerContract.x();
    }

    function getInnerContractAddr() public view returns (address) {
        return address(innerContract);
    }

    function incrementInnerContractX() public{
        innerContract.increment();
    }

    function createAndEndowCreated(uint arg, uint amount) public payable {
        // Send ether along with the creation
        CreatedWithEvent newCreated = new CreatedWithEvent{value: amount}(arg);
        newCreated.x();
    }
    function gasGuzzlerOuter(uint n, uint m) external{
        innerContract.gasGuzzlerInner(n, m);
    }
}

contract CreatedWithEvent {
    uint public x;
    address creator;

    event Incremented( address indexed from, uint value );
    event Deposited( address indexed from, uint value );

    constructor(uint a) payable {
        x = a;
        creator = msg.sender;
    }

    function increment() public {
        x += 1;
        emit Incremented(msg.sender, 1);
    }

    function incrementByArg(uint _x) public {
        x += _x;
        emit Incremented(msg.sender, _x);
    }
    function get() public view returns (uint)    {
        return x;
    }
    receive() payable external{
        emit Deposited(msg.sender, msg.value);
    }

    function deposit() payable external{
        emit Deposited(msg.sender, msg.value);
    }
    function withdraw() external{
        require(msg.sender == creator, "Only creator may withdraw funds");
        payable(creator).transfer(address(this).balance);
    }

    function gasGuzzlerInner(uint n, uint m) external{
        require(m > 0, "Negative parameter causes a revert");
        if(m > x){
            for (uint256 i = 0; i < n; i++) {
                increment();
            }
        }
    }
}

    function gasGuzzlerInner(uint n, uint m) external{
        emit GasUsed(true, gasleft());
        require(m > 0, "Negative parameter causes a revert");
        if(m > x){
            for (uint256 i = 0; i < n; i++) {
                increment();
            }
        }
        emit GasUsed(false, gasleft());
    }

// ... CreatorGas ...
    function createAndEndowCreated(uint arg, uint amount) public payable {
        // Send ether along with the creation
        CreatedWithEvent newCreated = new CreatedWithEvent{value: amount}(arg);
        newCreated.x();
    }

    event GasUsed(bool beginning, uint value );

    function gasGuzzlerOuter(uint n, uint m) external{
        emit GasUsed(true, gasleft());
        innerContract.gasGuzzlerInner(n, m);
        emit GasUsed(false, gasleft());
    }
}

