import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { network } from "hardhat";

describe("Ex2 - saldi del contratto", async function () {
  const { viem, networkHelpers } = await network.create();
  const [defaultWallet, aliceWallet, bobWallet] = await viem.getWalletClients();
  const publicClient = await viem.getPublicClient();

  async function fixture() {
    const created = await viem.deployContract("CreatedWithEvent", [10n]);
    return { created };
  }

  it("deposito via receive(): i fondi passano da Bob al contratto", async function () {
    const { created } = await networkHelpers.loadFixture(fixture);
    await viem.assertions.balancesHaveChanged(
      bobWallet.sendTransaction({ to: created.address, value: 5n * 10n ** 9n }),
      [
        { address: created.address, amount: 5n * 10n ** 9n },
        { address: bobWallet.account.address, amount: -(5n * 10n ** 9n) },
      ],
    );
  });

  it("withdraw svuota il contratto verso il creator", async function () {
    const { created } = await networkHelpers.loadFixture(fixture);
    await created.write.deposit({ account: aliceWallet.account, value: 3n * 10n ** 9n });
    await viem.assertions.balancesHaveChanged(
      created.write.withdraw(),
      [
        { address: created.address, amount: -(3n * 10n ** 9n) },
        { address: defaultWallet.account.address, amount: 3n * 10n ** 9n },
      ],
    );
    assert.equal(await publicClient.getBalance({ address: created.address }), 0n);
  });

  it("withdraw da Alice fa revert e il saldo resta", async function () {
    const { created } = await networkHelpers.loadFixture(fixture);
    await created.write.deposit({ account: aliceWallet.account, value: 1000n });
    await viem.assertions.revertWith(
      created.write.withdraw({ account: aliceWallet.account }),
      "Only creator may withdraw funds",
    );
    assert.equal(await publicClient.getBalance({ address: created.address }), 1000n);
  });
});

