import { describe, it } from "node:test";
import { network } from "hardhat";

describe("Ex4 - costo marginale del ciclo e limite del blocco", async function () {
  const { viem, networkHelpers } = await network.create();
  const [defaultWallet] = await viem.getWalletClients();
  const publicClient = await viem.getPublicClient();

  async function fixture() {
    const created = await viem.deployContract("CreatedWithEvent", [10n]);
    const creator = await viem.deployContract("Creator");
    await creator.write.overrideCreated([created.address]);
    return { creator };
  }

  it("gas in funzione di n", async function () {
    const gas: Record<string, bigint> = {};
    for (const n of [100n, 1000n]) {
      const { creator } = await networkHelpers.loadFixture(fixture);
      const tx = await creator.write.gasGuzzlerOuter([n, 11n]);
      gas[n.toString()] = (await publicClient.getTransactionReceipt({ hash: tx })).gasUsed;
    }
    const perIter = (gas["1000"] - gas["100"]) / 900n;
    const fixed = gas["100"] - 100n * perIter;
    const limit = (await publicClient.getBlock()).gasLimit;
    const nMax = (limit - fixed) / perIter;
    console.log("gas(100)=%d gas(1000)=%d", gas["100"], gas["1000"]);
    console.log("per iterazione ~%d, parte fissa ~%d", perIter, fixed);
    console.log("block gas limit %d -> n massimo ~%d", limit, nMax);
    console.log("n=100000 richiederebbe ~%d gas", fixed + 100000n * perIter);
  });
});

