import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { network } from "hardhat";

describe("Ex5 - somma degli eventi = stato", async function () {
  const { viem } = await network.create();
  const publicClient = await viem.getPublicClient();

  it("la somma dei valori di Incremented ricostruisce x", async function () {
    const created = await viem.deployContract("CreatedWithEvent", [10n]);
    const fromBlock = await publicClient.getBlockNumber();
    for (let i = 1n; i <= 10n; i++) {
      await created.write.incrementByArg([i]);
    }
    await created.write.increment();
    const events = await publicClient.getContractEvents({
      address: created.address,
      abi: created.abi,
      eventName: "Incremented",
      fromBlock,
      strict: true,
    });
    let total = 0n;
    for (const ev of events) total += ev.args.value;
    console.log("eventi: %d, somma: %d, x: %d", events.length, total, await created.read.x());
    assert.equal(10n + total, await created.read.x());
  });
});
